<?php
namespace App\Models;
use App\Services\InvoiceCalculator; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Database\Eloquent\Relations\MorphMany;
abstract class Invoice extends Model { use SoftDeletes; protected $guarded=[]; protected $casts=['issue_date'=>'date','due_date'=>'date','discount_value'=>'decimal:2','tax_rate'=>'decimal:2','subtotal'=>'decimal:2','discount_amount'=>'decimal:2','tax_amount'=>'decimal:2','total'=>'decimal:2']; public function items(): MorphMany { return $this->morphMany(InvoiceItem::class, 'invoice'); } public function payments(): MorphMany { return $this->morphMany(Payment::class, 'invoice'); } public function refreshStatus(): static { $paid = $this->payments()->sum('amount'); $this->status = bccomp((string)$paid, (string)$this->total, 2) >= 0 ? 'Paid' : ($this->due_date?->isPast() ? 'Overdue' : 'Pending'); $this->saveQuietly(); return $this; } public function getPaidAmountAttribute(): string { return number_format((float)$this->payments()->sum('amount'), 2, '.', ''); } }
